import java.util.*;

public class Ex07FailFast {
    public static void main(String[] args) {
        List<String> list = new ArrayList<>(List.of("a", "b", "c"));
        try {
            for (String s : list) {
                if (s.equals("a")) list.remove(s);
            }
            System.out.println("no exception, size=" + list.size());
        } catch (ConcurrentModificationException e) {
            System.out.println("caught ConcurrentModificationException: " + e.getClass().getSimpleName());
        }
    }
}
